 /* DBus limits packet length to 2^27. AllJoyn limits it further to 2^17 + 4096 to allow for 2^17 payload */
 #define MAX_PACKET_LEN (MAX_ARRAY_LEN + 4096)

+/* Arbitrarily chosen. */
+#define MAX_RECURSION_DEPTH 10
