+            advance_to_end_of_signature(pinfo, signature, signature_length);
             break;

         case ARG_BYTE:
@@ -797,6 +805,7 @@ advance_to_end_of_signature(const guint8 **signature,
             break;
         }
     }
+    p_set_proto_depth(pinfo, proto_AllJoyn_mess, recursion_depth);
 }

